package za.co.gpbrij.cph.api;
import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import za.co.gpbrij.cph.service.PaymentService; import java.util.List;
@RestController @RequestMapping("/api/v1/payments") public class PaymentController { private final PaymentService service; public PaymentController(PaymentService s){service=s;} @PostMapping ResponseEntity<PaymentView> create(@Valid @RequestBody CreatePaymentRequest r,@RequestHeader(name="X-Actor",defaultValue="demo.maker") String actor){return ResponseEntity.status(201).body(service.create(r,actor));} @GetMapping List<PaymentView> all(){return service.all();} @GetMapping("/{id}") PaymentView one(@PathVariable String id){return service.one(id);} @PostMapping("/{id}/submit") PaymentView submit(@PathVariable String id,@RequestHeader(name="X-Actor",defaultValue="demo.maker") String actor){return service.submit(id,actor);} @PostMapping("/{id}/decision") PaymentView decision(@PathVariable String id,@Valid @RequestBody DecisionRequest r){return service.decide(id,r);} @PostMapping("/{id}/process") PaymentView process(@PathVariable String id,@RequestHeader(name="X-Actor",defaultValue="mock.gateway") String actor){return service.process(id,actor);} }
